package com.saludintegral.cita.services;
import org.springframework.stereotype.Service;import org.springframework.web.client.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.client.RestClient;import java.util.*;import com.saludintegral.cita.model.*;import com.saludintegral.cita.repository.CitaRepository;import com.saludintegral.cita.dto.*;
@Service public class CitaService{final CitaRepository r;final RestClient paciente,medico;public CitaService(CitaRepository r,RestClient.Builder b,@Value("$"+"{paciente-url}")String pu,@Value("$"+"{medico-url}")String mu){this.r=r;paciente=b.baseUrl(pu).build();medico=b.baseUrl(mu).build();}
void check(RestClient c,String resource,Long id){try{c.get().uri("/api/"+resource+"/{id}",id).retrieve().toBodilessEntity();}catch(HttpClientErrorException.NotFound e){throw new NoSuchElementException(resource+" no encontrado: "+id);}catch(RestClientException e){throw new IllegalStateException("Servicio "+resource+" no disponible");}}
public List<Cita> all(){return r.findAll();}public Cita get(Long id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Cita no encontrada: "+id));}
public Cita create(CitaRequest x){check(paciente,"pacientes",x.idPaciente());check(medico,"medicos",x.idMedico());Cita c=new Cita();c.fecha=x.fecha();c.hora=x.hora();c.idPaciente=x.idPaciente();c.idMedico=x.idMedico();c.motivo=x.motivo();return r.save(c);}
public Cita estado(Long id,EstadoCita e){Cita c=get(id);if(c.estado==EstadoCita.CANCELADA)throw new IllegalArgumentException("La cita cancelada no puede cambiar de estado");c.estado=e;return r.save(c);}public Cita cancelar(Long id){Cita c=get(id);if(c.estado==EstadoCita.ATENDIDA)throw new IllegalArgumentException("Una cita atendida no puede cancelarse");c.estado=EstadoCita.CANCELADA;return r.save(c);}}
